use super::*;

/// The inverse of [`to_fmt`] — a spec that came back out of the shared renderer, in this crate's type.
pub(crate) fn from_fmt(s: &bsc_record::imports_fmt::ImportSpec) -> ImportSpec {
    ImportSpec {
        from: s.from.clone(),
        symbols: s.symbols.clone(),
        type_only: s.type_only,
        kind: s.kind.clone(),
    }
}
